<?php require 'config/config.php';auth();$s=db()->prepare("SELECT b.*,r.room_number,r.rent,p.title,p.city FROM bookings b JOIN rooms r ON r.id=b.room_id JOIN properties p ON p.id=r.property_id WHERE b.id=? AND b.user_id=?");$s->execute([(int)$_GET['booking_id'],user()['id']]);$b=$s->fetch();if(!$b)exit('Booking not found');if($_POST){check();$txn='ST'.date('YmdHis').random_int(100,999);db()->beginTransaction();db()->prepare("INSERT INTO payments(booking_id,user_id,amount,method,transaction_id,status,paid_at) VALUES(?,?,?,?,?,?,NOW())")->execute([$b['id'],user()['id'],$b['advance_amount'],$_POST['method'],$txn,'success']);db()->prepare("UPDATE bookings SET status='confirmed',payment_status='paid',payment_transaction_id=? WHERE id=?")->execute([$txn,$b['id']]);db()->prepare("UPDATE rooms SET status='occupied' WHERE id=?")->execute([$b['room_id']]);$aid=agreement($b['id'],$txn);db()->commit();go(BASE_URL.'/agreement.php?id='.$aid);}$title='Payment';require 'config/header.php';?><div class="auth"><div class="panel"><small>DEMO PAYMENT</small><h1>Confirm booking</h1><div class="pay"><span>Advance payable</span><b><?=money($b['advance_amount'])?></b></div><p class="notice">No real money is charged. This records a successful demo payment in MySQL.</p><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Payment method<select name="method"><option>UPI</option><option>Card</option><option>Net Banking</option></select></label><button class="btn">Pay <?=money($b['advance_amount'])?></button></form></div></div><?php require 'config/footer.php';?>
